### 核心服务契约与接口定义（包含回收区 7 天生命周期管理接口）

1. **存储服务接口 (`IStorageService`)**：
```typescript
export interface IStorageService {
  // 数据库生命周期
  init(): Promise<void>;
  close(): Promise<void>;

  // 持久化保护与配额
  requestPersistence(): Promise<boolean>;
  isPersisted(): Promise<boolean>;
  getStorageQuota(): Promise<{ usage: number; quota: number; percentUsed: number }>;

  // 便签基础 CRUD 操作
  getNoteById(id: string): Promise<Note | null>;
  listNotes(filter?: {
    status?: NoteStatus;
    isFavorite?: boolean;
    isPinned?: boolean;
    tags?: string[];
  }): Promise<Note[]>;
  saveNote(note: Note): Promise<void>;

  // 回收区与生命周期专属方法（响应 7 天保留与超期永久删除需求）
  moveToTrash(id: string): Promise<void>;                  // 移入回收区：设置 status='trashed', trashedAt=Date.now(), isPinned=false
  restoreFromTrash(id: string): Promise<void>;             // 回收区还原：恢复 status='active', trashedAt=null
  listTrashNotes(): Promise<Note[]>;                       // 列出回收区内所有便签（按 trashedAt 降序）
  getExpiredTrashNotes(retentionDays?: number): Promise<Note[]>; // 检索超过 7 天（默认 7 天）的超期便签
  permanentlyDeleteNotes(ids: string[]): Promise<{ deletedCount: number }>; // 批量永久物理删除（不可逆）
  emptyTrash(): Promise<{ deletedCount: number }>;         // 清空回收区中全部便签

  // 批量操作
  batchUpdateTags(oldTag: string, newTag: string): Promise<{ affectedCount: number }>;
  batchImportNotes(notes: Note[], mode: 'merge' | 'overwrite'): Promise<{ inserted: number; updated: number }>;
  clearAllData(): Promise<void>;

  // 元数据管理
  getMeta<T>(key: string): Promise<T | null>;
  setMeta<T>(key: string, value: T): Promise<void>;
}
```

2. **检索服务接口 (`ISearchService`)**：
```typescript
export interface SearchQueryOptions {
  query: string;               // 搜索文本，支持正文关键词与 "#tag" 过滤
  activeStatus?: NoteStatus;   // 状态过滤，默认为 'active'（排除 'trashed'）
  activeTags?: string[];       // 选中的标签交集过滤列表
  onlyFavorites?: boolean;     // 是否仅筛选已收藏便签
  includeTrash?: boolean;      // 是否包含回收区便签，默认 false
}

export interface SearchHit {
  note: Note;
  matchedFields: ('content' | 'tags')[];
  highlightedContent: string;
}

export interface ISearchService {
  setIndexSource(notes: Note[]): void;
  search(options: SearchQueryOptions): {
    results: SearchHit[];
    totalMatched: number;
    searchDurationMs: number;
  };
}
```

3. **备份服务接口 (`IBackupService`)**：
```typescript
export interface IBackupService {
  exportJsonBackup(options?: { includeTrash?: boolean }): Promise<{ blob: Blob; fileName: string; count: number }>;
  exportMarkdownBundle(): Promise<{ blob: Blob; fileName: string; count: number }>;
  validateBackupFile(rawJsonText: string): {
    valid: boolean;
    errorReason?: string;
    payload?: BackupPayload;
  };
  executeImport(payload: BackupPayload, mode: 'merge' | 'overwrite'): Promise<{
    success: boolean;
    insertedCount: number;
    updatedCount: number;
  }>;
  checkBackupReminderNeeded(tracker: BackupTrackerMeta): boolean;
  detectPrivateMode(): Promise<boolean>;
}
```

4. **Markdown 解析服务接口 (`IMarkdownService`)**：
```typescript
export interface IMarkdownService {
  renderToSafeHtml(markdownText: string): string;
  extractTagsFromText(text: string): string[];
}
```
